      "That number": "\u8FD9\u4E2A\u53F7\u7801",
      "This photo didn't come through in full from your phone. Please take it again or choose another photo.": "\u8FD9\u5F20\u7167\u7247\u6CA1\u6709\u4ECE\u60A8\u7684\u624B\u673A\u5B8C\u6574\u4F20\u9001\u3002\u8BF7\u91CD\u65B0\u62CD\u6444\u6216\u9009\u62E9\u53E6\u4E00\u5F20\u7167\u7247\u3002",
      "Plans are managed on the Sellio website": "\u65B9\u6848\u5728 Sellio \u7F51\u7AD9\u4E0A\u7BA1\u7406",
      "Google sign-in isn\u2019t working for this account in the app. Please sign in with your phone number or email instead.": "\u8FD9\u4E2A\u8D26\u53F7\u65E0\u6CD5\u5728\u5E94\u7528\u4E2D\u4F7F\u7528 Google \u767B\u5F55\u3002\u8BF7\u6539\u7528\u624B\u673A\u53F7\u7801\u6216\u90AE\u7BB1\u767B\u5F55\u3002",
