      "We\u2019ll email you a 6-digit code. No password needed.": "\u6211\u4EEC\u4F1A\u53D1\u9001 6 \u4F4D\u9A8C\u8BC1\u7801\u5230\u60A8\u7684\u90AE\u7BB1\uFF0C\u65E0\u9700\u5BC6\u7801\u3002",
      "Email me a code": "\u53D1\u9001\u9A8C\u8BC1\u7801\u5230\u6211\u7684\u90AE\u7BB1",
      "Code sent to {email}": "\u9A8C\u8BC1\u7801\u5DF2\u53D1\u9001\u81F3 {email}",
