      "No confirmed orders": "\u6CA1\u6709\u5DF2\u786E\u8BA4\u7684\u8BA2\u5355",
      "\u{1F7E3} Preparing ({count})": "\u{1F7E3} \u51C6\u5907\u4E2D\uFF08{count}\uFF09",
      "No orders being prepared": "\u6CA1\u6709\u51C6\u5907\u4E2D\u7684\u8BA2\u5355",
      "\u{1F7E2} Ready ({count})": "\u{1F7E2} \u5DF2\u5907\u597D\uFF08{count}\uFF09",
      "No ready orders": "\u6CA1\u6709\u5DF2\u5907\u597D\u7684\u8BA2\u5355",
      "Please take a clear photo of your menu.": "\u8BF7\u62CD\u4E00\u5F20\u6E05\u6670\u7684\u83DC\u5355\u7167\u7247\u3002",
      "Could not read this photo. Please take another one.": "\u65E0\u6CD5\u8BFB\u53D6\u8FD9\u5F20\u7167\u7247\uFF0C\u8BF7\u91CD\u65B0\u62CD\u4E00\u5F20\u3002",
      "Scan failed. Please try again.": "\u626B\u63CF\u5931\u8D25\uFF0C\u8BF7\u91CD\u8BD5\u3002",
      "No items found. Try a clearer photo.": "\u6CA1\u6709\u627E\u5230\u5546\u54C1\u3002\u8BF7\u8BD5\u8BD5\u66F4\u6E05\u6670\u7684\u7167\u7247\u3002",
      "Your plan allows up to {max} products (1 slot left). Deselect some items or upgrade your plan to add all {count}.": "\u60A8\u7684\u65B9\u6848\u6700\u591A\u53EF\u6709 {max} \u4EF6\u5546\u54C1\uFF08\u8FD8\u5269 1 \u4E2A\u540D\u989D\uFF09\u3002\u8BF7\u53D6\u6D88\u9009\u62E9\u90E8\u5206\u5546\u54C1\uFF0C\u6216\u5347\u7EA7\u65B9\u6848\u4EE5\u6DFB\u52A0\u5168\u90E8 {count} \u4EF6\u3002",
      "Your plan allows up to {max} products ({remaining} slots left). Deselect some items or upgrade your plan to add all {count}.": "\u60A8\u7684\u65B9\u6848\u6700\u591A\u53EF\u6709 {max} \u4EF6\u5546\u54C1\uFF08\u8FD8\u5269 {remaining} \u4E2A\u540D\u989D\uFF09\u3002\u8BF7\u53D6\u6D88\u9009\u62E9\u90E8\u5206\u5546\u54C1\uFF0C\u6216\u5347\u7EA7\u65B9\u6848\u4EE5\u6DFB\u52A0\u5168\u90E8 {count} \u4EF6\u3002",
      "Scan Menu": "\u626B\u63CF\u83DC\u5355",
      "Reading your menu\u2026": "\u6B63\u5728\u8BFB\u53D6\u60A8\u7684\u83DC\u5355\u2026",
      "Try again or take another photo": "\u8BF7\u91CD\u8BD5\u6216\u91CD\u65B0\u62CD\u7167",
      "Take another photo": "\u518D\u62CD\u4E00\u5F20",
      "Products added successfully!": "\u5546\u54C1\u5DF2\u6210\u529F\u6DFB\u52A0\uFF01",
      "Close menu scan": "\u5173\u95ED\u83DC\u5355\u626B\u63CF",
      "Menu being scanned": "\u6B63\u5728\u626B\u63CF\u7684\u83DC\u5355",
      "Try Again": "\u91CD\u8BD5",
      Retake: "\u91CD\u62CD",
      "Retake menu photo": "\u91CD\u62CD\u83DC\u5355\u7167\u7247",
      "{selectedCount} of {count} selected": "\u5DF2\u9009 {selectedCount}/{count}",
      "Select all": "\u5168\u9009",
      "Product name": "\u5546\u54C1\u540D\u79F0",
      Category: "\u5206\u7C7B",
      "Description (optional)": "\u63CF\u8FF0\uFF08\u9009\u586B\uFF09",
      "Upgrade Plan": "\u5347\u7EA7\u65B9\u6848",
      "Products Added!": "\u5546\u54C1\u5DF2\u6DFB\u52A0\uFF01",
      "{selectedCount} products have been added to your catalog.": "\u5DF2\u5C06 {selectedCount} \u4EF6\u5546\u54C1\u6DFB\u52A0\u5230\u60A8\u7684\u5546\u54C1\u76EE\u5F55\u3002",
      "Scan another menu photo": "\u626B\u63CF\u53E6\u4E00\u5F20\u83DC\u5355\u7167\u7247",
      "This photo doesn\u2019t look like a menu. Take a photo of the menu or price list.": "\u8FD9\u5F20\u7167\u7247\u770B\u8D77\u6765\u4E0D\u50CF\u83DC\u5355\u3002\u8BF7\u62CD\u6444\u83DC\u5355\u6216\u4EF7\u76EE\u8868\u3002",
      "The menu is too blurry to read. Hold the phone steady, get closer and make sure the menu is well lit.": "\u83DC\u5355\u592A\u6A21\u7CCA\uFF0C\u65E0\u6CD5\u8BFB\u53D6\u3002\u8BF7\u62FF\u7A33\u624B\u673A\u3001\u9760\u8FD1\u4E00\u70B9\uFF0C\u5E76\u786E\u4FDD\u83DC\u5355\u5149\u7EBF\u5145\u8DB3\u3002",
      "Only part of the menu is in the photo. Step back so the whole menu fits, or scan it in parts.": "\u7167\u7247\u91CC\u53EA\u6709\u90E8\u5206\u83DC\u5355\u3002\u8BF7\u9000\u540E\u4E00\u70B9\uFF0C\u8BA9\u6574\u4EFD\u83DC\u5355\u5165\u955C\uFF0C\u6216\u5206\u6BB5\u626B\u63CF\u3002",
      "No items to order were found in this photo. Try a clearer photo of the menu.": "\u8FD9\u5F20\u7167\u7247\u4E2D\u6CA1\u6709\u627E\u5230\u53EF\u70B9\u7684\u5546\u54C1\u3002\u8BF7\u62CD\u4E00\u5F20\u66F4\u6E05\u6670\u7684\u83DC\u5355\u7167\u7247\u3002",
      "This menu is too long to read in one go. Scan half of it at a time.": "\u8FD9\u4EFD\u83DC\u5355\u592A\u957F\uFF0C\u65E0\u6CD5\u4E00\u6B21\u8BFB\u5B8C\u3002\u8BF7\u6BCF\u6B21\u626B\u63CF\u4E00\u534A\u3002",
      "Couldn\u2019t keep that photo. Please try again.": "\u65E0\u6CD5\u4FDD\u7559\u90A3\u5F20\u7167\u7247\uFF0C\u8BF7\u91CD\u8BD5\u3002",
      "Add a price for 1 selected item, or deselect it.": "\u8BF7\u4E3A 1 \u4EF6\u5DF2\u9009\u5546\u54C1\u6DFB\u52A0\u4EF7\u683C\uFF0C\u6216\u53D6\u6D88\u9009\u62E9\u3002",
      "Add a price for {count} selected items, or deselect them.": "\u8BF7\u4E3A {count} \u4EF6\u5DF2\u9009\u5546\u54C1\u6DFB\u52A0\u4EF7\u683C\uFF0C\u6216\u53D6\u6D88\u9009\u62E9\u3002",
      "This menu is long, so only part of it was read. Scan the rest in another photo.": "\u8FD9\u4EFD\u83DC\u5355\u8F83\u957F\uFF0C\u53EA\u8BFB\u53D6\u4E86\u4E00\u90E8\u5206\u3002\u8BF7\u518D\u62CD\u4E00\u5F20\u626B\u63CF\u5176\u4F59\u90E8\u5206\u3002",
      "1 item has no price on the menu. Add it below, or deselect it.": "\u6709 1 \u4EF6\u5546\u54C1\u5728\u83DC\u5355\u4E0A\u6CA1\u6709\u4EF7\u683C\u3002\u8BF7\u5728\u4E0B\u65B9\u6DFB\u52A0\uFF0C\u6216\u53D6\u6D88\u9009\u62E9\u3002",
      "{count} items have no price on the menu. Add them below, or deselect them.": "\u6709 {count} \u4EF6\u5546\u54C1\u5728\u83DC\u5355\u4E0A\u6CA1\u6709\u4EF7\u683C\u3002\u8BF7\u5728\u4E0B\u65B9\u6DFB\u52A0\uFF0C\u6216\u53D6\u6D88\u9009\u62E9\u3002",
      "Tap a photo to change it": "\u70B9\u6309\u7167\u7247\u5373\u53EF\u66F4\u6362",
