      "Show Order Number": "\u663E\u793A\u8BA2\u5355\u53F7",
      "Footer Message": "\u9875\u811A\u4FE1\u606F",
      "e.g. Thank you for dining with us!": "\u4F8B\u5982\uFF1A\u611F\u8C22\u60A8\u7684\u5149\u4E34\uFF01",
