      "New orders will be numbered from this value. Existing order numbers are unaffected.": "\u65B0\u8BA2\u5355\u5C06\u4ECE\u8FD9\u4E2A\u53F7\u7801\u5F00\u59CB\u7F16\u53F7\uFF0C\u73B0\u6709\u8BA2\u5355\u53F7\u4E0D\u53D7\u5F71\u54CD\u3002",
