      "Upgrade \u2192": "\u5347\u7EA7 \u2192",
      "Your subscription has ended": "\u60A8\u7684\u8BA2\u9605\u5DF2\u7ED3\u675F",
      "Your trial has ended": "\u60A8\u7684\u8BD5\u7528\u5DF2\u7ED3\u675F",
      "Your data is safe and comes back as soon as your plan is active again.": "\u60A8\u7684\u8D44\u6599\u5F88\u5B89\u5168\uFF0C\u65B9\u6848\u91CD\u65B0\u751F\u6548\u540E\u5C31\u4F1A\u6062\u590D\u3002",
      "Resubscribe to {previousPlanName} or choose another plan to continue. Your data is safe and returns as soon as you subscribe.": "\u91CD\u65B0\u8BA2\u9605 {previousPlanName} \u6216\u9009\u62E9\u5176\u4ED6\u65B9\u6848\u4EE5\u7EE7\u7EED\u4F7F\u7528\u3002\u60A8\u7684\u8D44\u6599\u5F88\u5B89\u5168\uFF0C\u8BA2\u9605\u540E\u7ACB\u5373\u6062\u590D\u3002",
      "Choose a plan to continue using Sellio. Your data is safe and returns as soon as you subscribe.": "\u9009\u62E9\u65B9\u6848\u4EE5\u7EE7\u7EED\u4F7F\u7528 Sellio\u3002\u60A8\u7684\u8D44\u6599\u5F88\u5B89\u5168\uFF0C\u8BA2\u9605\u540E\u7ACB\u5373\u6062\u590D\u3002",
      "Bill annually": "\u6309\u5E74\u4ED8\u8D39",
      Annual: "\u6309\u5E74",
      "Your previous plan": "\u60A8\u4E4B\u524D\u7684\u65B9\u6848",
      "Current plan": "\u5F53\u524D\u65B9\u6848",
      month: "\u6708",
      year: "\u5E74",
      "Save SGD {saving}": "\u8282\u7701 SGD {saving}",
      "Wrong account?": "\u8D26\u53F7\u4E0D\u5BF9\uFF1F",
      "Access Restricted": "\u8BBF\u95EE\u53D7\u9650",
      "You don't have permission to view this section. Contact your administrator to request access.": "\u60A8\u6CA1\u6709\u67E5\u770B\u6B64\u90E8\u5206\u7684\u6743\u9650\u3002\u8BF7\u8054\u7CFB\u7BA1\u7406\u5458\u7533\u8BF7\u6743\u9650\u3002",
      "Permission Required": "\u9700\u8981\u6743\u9650",
      "This feature requires special permissions. Please contact your administrator.": "\u8FD9\u9879\u529F\u80FD\u9700\u8981\u7279\u522B\u6743\u9650\uFF0C\u8BF7\u8054\u7CFB\u7BA1\u7406\u5458\u3002",
      "Alerts are on for this browser": "\u8FD9\u4E2A\u6D4F\u89C8\u5668\u5DF2\u5F00\u542F\u63D0\u9192",
      "Alerts are on for this phone": "\u8FD9\u90E8\u624B\u673A\u5DF2\u5F00\u542F\u63D0\u9192",
      "On for this browser. Change them in your browser's settings for this site.": "\u8FD9\u4E2A\u6D4F\u89C8\u5668\u5DF2\u5F00\u542F\u3002\u53EF\u5728\u6D4F\u89C8\u5668\u4E2D\u6B64\u7F51\u7AD9\u7684\u8BBE\u7F6E\u91CC\u66F4\u6539\u3002",
      "Off in this browser": "\u8FD9\u4E2A\u6D4F\u89C8\u5668\u5DF2\u5173\u95ED",
      "Off. Allow notifications for this site in your browser's settings.": "\u5DF2\u5173\u95ED\u3002\u8BF7\u5728\u6D4F\u89C8\u5668\u8BBE\u7F6E\u4E2D\u5141\u8BB8\u6B64\u7F51\u7AD9\u53D1\u9001\u901A\u77E5\u3002",
      "On for this phone. Change them in your phone's settings for Sellio.": "\u8FD9\u90E8\u624B\u673A\u5DF2\u5F00\u542F\u3002\u53EF\u5728\u624B\u673A\u7684 Sellio \u8BBE\u7F6E\u4E2D\u66F4\u6539\u3002",
      "Off on this phone": "\u8FD9\u90E8\u624B\u673A\u5DF2\u5173\u95ED",
      "Off for Sellio on this phone, so new orders won\u2019t ring here.": "\u8FD9\u90E8\u624B\u673A\u5DF2\u5173\u95ED Sellio \u7684\u901A\u77E5\uFF0C\u6240\u4EE5\u65B0\u8BA2\u5355\u4E0D\u4F1A\u5728\u8FD9\u91CC\u54CD\u94C3\u3002",
      "Off. Turn them on in your phone's Settings: Apps \u2192 Sellio \u2192 Notifications.": "\u5DF2\u5173\u95ED\u3002\u8BF7\u5728\u624B\u673A\u7684\u201C\u8BBE\u7F6E\u201D\u4E2D\u5F00\u542F\uFF1A\u5E94\u7528 \u2192 Sellio \u2192 \u901A\u77E5\u3002",
      "Browser alerts": "\u6D4F\u89C8\u5668\u63D0\u9192",
      "Phone alerts": "\u624B\u673A\u63D0\u9192",
      "Turn on": "\u5F00\u542F",
