      "Couldn\u2019t save your profile": "\u65E0\u6CD5\u4FDD\u5B58\u60A8\u7684\u4E2A\u4EBA\u8D44\u6599",
      "Passwords do not match": "\u4E24\u6B21\u8F93\u5165\u7684\u5BC6\u7801\u4E0D\u4E00\u81F4",
      "Password must be at least 6 characters": "\u5BC6\u7801\u81F3\u5C11\u9700\u8981 6 \u4E2A\u5B57\u7B26",
