      "Phone alerts are off for Sellio, so new orders won\u2019t ring on this phone.": "\u8FD9\u90E8\u624B\u673A\u5DF2\u5173\u95ED Sellio \u7684\u63D0\u9192\uFF0C\u6240\u4EE5\u65B0\u8BA2\u5355\u4E0D\u4F1A\u5728\u8FD9\u90E8\u624B\u673A\u4E0A\u54CD\u94C3\u3002",
      "Get alerts for new orders": "\u63A5\u6536\u65B0\u8BA2\u5355\u63D0\u9192",
      "In this browser, even when Sellio is closed": "\u5728\u8FD9\u4E2A\u6D4F\u89C8\u5668\u4E2D\uFF0C\u5373\u4F7F Sellio \u5DF2\u5173\u95ED",
      "On this phone, even when Sellio is closed": "\u5728\u8FD9\u90E8\u624B\u673A\u4E0A\uFF0C\u5373\u4F7F Sellio \u5DF2\u5173\u95ED",
      "Alerts in this browser from the shop": "\u5728\u8FD9\u4E2A\u6D4F\u89C8\u5668\u4E2D\u63A5\u6536\u5E97\u5BB6\u7684\u63D0\u9192",
      "Alerts on this phone from the shop": "\u5728\u8FD9\u90E8\u624B\u673A\u4E0A\u63A5\u6536\u5E97\u5BB6\u7684\u63D0\u9192",
      "Know when your order is ready": "\u8BA2\u5355\u5907\u597D\u65F6\u901A\u77E5\u60A8",
      "Alerts in this browser, even when Sellio is closed": "\u5728\u8FD9\u4E2A\u6D4F\u89C8\u5668\u4E2D\u63A5\u6536\u63D0\u9192\uFF0C\u5373\u4F7F Sellio \u5DF2\u5173\u95ED",
      "Alerts on this phone, even when Sellio is closed": "\u5728\u8FD9\u90E8\u624B\u673A\u4E0A\u63A5\u6536\u63D0\u9192\uFF0C\u5373\u4F7F Sellio \u5DF2\u5173\u95ED",
      "Know when they reply": "\u5BF9\u65B9\u56DE\u590D\u65F6\u901A\u77E5\u60A8",
      "Not now": "\u6682\u65F6\u4E0D\u8981",
      TOTAL: "\u603B\u8BA1",
      "Orders:": "\u8BA2\u5355\uFF1A",
      "Order Chit": "\u53A8\u623F\u5355",
      "ORDER NOTE:": "\u8BA2\u5355\u5907\u6CE8\uFF1A",
      "My Store": "\u6211\u7684\u5E97\u94FA",
      "** TEST PRINT **": "** \u6D4B\u8BD5\u6253\u5370 **",
      "Cashier:": "\u6536\u94F6\u5458\uFF1A",
      "Subtotal:": "\u5C0F\u8BA1\uFF1A",
      "TOTAL:": "\u603B\u8BA1\uFF1A",
      "Printer not connected. Please go to Settings \u2192 Receipt \u2192 Printer and reconnect.": "\u6253\u5370\u673A\u672A\u8FDE\u63A5\u3002\u8BF7\u524D\u5F80\u201C\u8BBE\u7F6E \u2192 \u6536\u636E \u2192 \u6253\u5370\u673A\u201D\u91CD\u65B0\u8FDE\u63A5\u3002",
      "Web Bluetooth not supported": "\u4E0D\u652F\u6301 Web Bluetooth",
      "No compatible printer service found. Tried {count} profiles. Last error: {error}. Try Network/IP mode if issue persists.": "\u627E\u4E0D\u5230\u517C\u5BB9\u7684\u6253\u5370\u673A\u670D\u52A1\u3002\u5DF2\u5C1D\u8BD5 {count} \u79CD\u914D\u7F6E\u3002\u6700\u540E\u7684\u9519\u8BEF\uFF1A{error}\u3002\u5982\u679C\u95EE\u9898\u6301\u7EED\uFF0C\u8BF7\u6539\u7528\u7F51\u7EDC/IP \u6A21\u5F0F\u3002",
      "ePOS error: {status}": "ePOS \u9519\u8BEF\uFF1A{status}",
      "Printer did not confirm the print": "\u6253\u5370\u673A\u672A\u786E\u8BA4\u6253\u5370",
