      "E-wallet": "\u7535\u5B50\u94B1\u5305",
      Served: "\u5DF2\u4E0A\u83DC",
      "Not paid yet": "\u5C1A\u672A\u4ED8\u6B3E",
      "Paid by {how}": "\u4EE5{how}\u4ED8\u6B3E",
      "Connect a compatible receipt printer in Settings \u2192 Business \u2192 Receipt Printer.": "\u8BF7\u5728\u201C\u8BBE\u7F6E \u2192 \u5546\u5BB6 \u2192 \u6536\u636E\u6253\u5370\u673A\u201D\u4E2D\u8FDE\u63A5\u517C\u5BB9\u7684\u6536\u636E\u6253\u5370\u673A\u3002",
      "Device storage is unavailable. Auto-print stopped to prevent duplicate chits.": "\u8BBE\u5907\u5B58\u50A8\u7A7A\u95F4\u4E0D\u53EF\u7528\u3002\u4E3A\u907F\u514D\u91CD\u590D\u6253\u5370\u53A8\u623F\u5355\uFF0C\u5DF2\u505C\u6B62\u81EA\u52A8\u6253\u5370\u3002",
      "Bluetooth permission is off for Sellio.": "Sellio \u7684\u84DD\u7259\u6743\u9650\u5DF2\u5173\u95ED\u3002",
      "Bluetooth is off. Turn it on and try again.": "\u84DD\u7259\u5DF2\u5173\u95ED\u3002\u8BF7\u5F00\u542F\u540E\u91CD\u8BD5\u3002",
      "This phone doesn't have Bluetooth printing.": "\u8FD9\u90E8\u624B\u673A\u4E0D\u652F\u6301\u84DD\u7259\u6253\u5370\u3002",
      "Bluetooth printing failed.": "\u84DD\u7259\u6253\u5370\u5931\u8D25\u3002",
      "Couldn't look for printers.": "\u65E0\u6CD5\u641C\u7D22\u6253\u5370\u673A\u3002",
      "Couldn't connect to {name}. Check it's on and nearby, then try again.": "\u65E0\u6CD5\u8FDE\u63A5\u5230 {name}\u3002\u8BF7\u786E\u8BA4\u5B83\u5DF2\u5F00\u542F\u4E14\u5728\u9644\u8FD1\uFF0C\u7136\u540E\u91CD\u8BD5\u3002",
      "{name} doesn't take prints. Choose your receipt printer.": "{name} \u65E0\u6CD5\u6253\u5370\u3002\u8BF7\u9009\u62E9\u60A8\u7684\u6536\u636E\u6253\u5370\u673A\u3002",
      "Couldn't reach the printer. Check it's on and nearby.": "\u65E0\u6CD5\u8FDE\u63A5\u6253\u5370\u673A\u3002\u8BF7\u786E\u8BA4\u5B83\u5DF2\u5F00\u542F\u4E14\u5728\u9644\u8FD1\u3002",
      "This Bluetooth device doesn't take prints. Choose your printer in Settings \u2192 Receipt \u2192 Printer.": "\u8FD9\u53F0\u84DD\u7259\u8BBE\u5907\u65E0\u6CD5\u6253\u5370\u3002\u8BF7\u5728\u201C\u8BBE\u7F6E \u2192 \u6536\u636E \u2192 \u6253\u5370\u673A\u201D\u4E2D\u9009\u62E9\u60A8\u7684\u6253\u5370\u673A\u3002",
      "The printer stopped part way. Check it has paper and is on, then print again.": "\u6253\u5370\u673A\u4E2D\u9014\u505C\u6B62\u3002\u8BF7\u786E\u8BA4\u5B83\u6709\u7EB8\u4E14\u5DF2\u5F00\u542F\uFF0C\u7136\u540E\u91CD\u65B0\u6253\u5370\u3002",
      "You can allow them later in your browser's settings for this site.": "\u60A8\u4E4B\u540E\u53EF\u4EE5\u5728\u6D4F\u89C8\u5668\u4E2D\u6B64\u7F51\u7AD9\u7684\u8BBE\u7F6E\u91CC\u5141\u8BB8\u63D0\u9192\u3002",
      "Alerts couldn't be turned on just now. Sellio tries again next time you open it.": "\u6682\u65F6\u65E0\u6CD5\u5F00\u542F\u63D0\u9192\u3002\u4E0B\u6B21\u6253\u5F00 Sellio \u65F6\u4F1A\u518D\u8BD5\u4E00\u6B21\u3002",
      "Turn on browser alerts": "\u5F00\u542F\u6D4F\u89C8\u5668\u63D0\u9192",
      "You can turn them on later in your phone's Settings: Apps \u2192 Sellio \u2192 Notifications.": "\u60A8\u4E4B\u540E\u53EF\u4EE5\u5728\u624B\u673A\u7684\u201C\u8BBE\u7F6E\u201D\u4E2D\u5F00\u542F\uFF1A\u5E94\u7528 \u2192 Sellio \u2192 \u901A\u77E5\u3002",
      "Turn on phone alerts": "\u5F00\u542F\u624B\u673A\u63D0\u9192",
      "Couldn\u2019t upload the logo": "Logo \u4E0A\u4F20\u5931\u8D25",
      "You\u2019re offline. Connect to the internet, then try again.": "\u60A8\u76EE\u524D\u79BB\u7EBF\u3002\u8BF7\u8FDE\u63A5\u7F51\u7EDC\u540E\u91CD\u8BD5\u3002",
      "Your phone couldn\u2019t reach Sellio. Check your internet connection, then try again.": "\u60A8\u7684\u624B\u673A\u65E0\u6CD5\u8FDE\u63A5 Sellio\u3002\u8BF7\u68C0\u67E5\u7F51\u7EDC\u8FDE\u63A5\u540E\u91CD\u8BD5\u3002",
      "You\u2019ve been signed out. Sign in again, then try again.": "\u60A8\u5DF2\u9000\u51FA\u767B\u5F55\u3002\u8BF7\u91CD\u65B0\u767B\u5F55\u540E\u518D\u8BD5\u3002",
      "Your account isn\u2019t allowed to do this. Ask the shop\u2019s owner for access.": "\u60A8\u7684\u8D26\u53F7\u6CA1\u6709\u6743\u9650\u6267\u884C\u6B64\u64CD\u4F5C\u3002\u8BF7\u5411\u5E97\u4E3B\u7533\u8BF7\u6743\u9650\u3002",
      "It\u2019s still used elsewhere in your shop, so it can\u2019t be removed yet.": "\u5B83\u4ECD\u5728\u60A8\u5E97\u94FA\u7684\u5176\u4ED6\u5730\u65B9\u4F7F\u7528\uFF0C\u6240\u4EE5\u6682\u65F6\u65E0\u6CD5\u79FB\u9664\u3002",
      "It was changed or removed somewhere else. Refresh the page, then try again.": "\u5B83\u5DF2\u5728\u522B\u5904\u88AB\u66F4\u6539\u6216\u79FB\u9664\u3002\u8BF7\u5237\u65B0\u9875\u9762\u540E\u91CD\u8BD5\u3002",
      "Some details weren\u2019t accepted. Check what you entered, then try again.": "\u90E8\u5206\u8D44\u6599\u672A\u88AB\u63A5\u53D7\u3002\u8BF7\u68C0\u67E5\u60A8\u8F93\u5165\u7684\u5185\u5BB9\u540E\u91CD\u8BD5\u3002",
      "A required detail is missing. Fill it in, then try again.": "\u7F3A\u5C11\u5FC5\u586B\u8D44\u6599\u3002\u8BF7\u586B\u5199\u540E\u91CD\u8BD5\u3002",
      "Some text is too long. Shorten it, then try again.": "\u90E8\u5206\u6587\u5B57\u592A\u957F\u3002\u8BF7\u7F29\u77ED\u540E\u91CD\u8BD5\u3002",
      "A number is too large. Check the amounts, then try again.": "\u67D0\u4E2A\u6570\u5B57\u592A\u5927\u3002\u8BF7\u68C0\u67E5\u91D1\u989D\u540E\u91CD\u8BD5\u3002",
      "Someone else changed this at the same moment. Refresh, check it, then try again.": "\u6709\u4EBA\u5728\u540C\u4E00\u65F6\u95F4\u66F4\u6539\u4E86\u6B64\u5185\u5BB9\u3002\u8BF7\u5237\u65B0\u5E76\u68C0\u67E5\u540E\u91CD\u8BD5\u3002",
      "That file is too big. Choose a smaller one, then try again.": "\u6587\u4EF6\u592A\u5927\u3002\u8BF7\u9009\u62E9\u8F83\u5C0F\u7684\u6587\u4EF6\u540E\u91CD\u8BD5\u3002",
      "That\u2019s a lot of tries in a short time. Wait a minute, then try again.": "\u77ED\u65F6\u95F4\u5185\u5C1D\u8BD5\u6B21\u6570\u592A\u591A\u3002\u8BF7\u7B49\u4E00\u5206\u949F\u540E\u91CD\u8BD5\u3002",
      "Sellio took too long to answer. That\u2019s on our side, not yours. Try again in a moment.": "Sellio \u56DE\u5E94\u65F6\u95F4\u592A\u957F\u3002\u8FD9\u662F\u6211\u4EEC\u8FD9\u8FB9\u7684\u95EE\u9898\uFF0C\u4E0D\u662F\u60A8\u7684\u95EE\u9898\u3002\u8BF7\u7A0D\u540E\u518D\u8BD5\u3002",
      "Something went wrong on Sellio\u2019s side, not yours. Try again in a moment. If it keeps happening, email {email}.": "Sellio \u8FD9\u8FB9\u51FA\u4E86\u95EE\u9898\uFF0C\u4E0D\u662F\u60A8\u7684\u95EE\u9898\u3002\u8BF7\u7A0D\u540E\u518D\u8BD5\u3002\u5982\u679C\u4E00\u76F4\u53D1\u751F\uFF0C\u8BF7\u53D1\u90AE\u4EF6\u5230 {email}\u3002",
      "That order number": "\u8FD9\u4E2A\u8BA2\u5355\u53F7",
      "That phone number": "\u8FD9\u4E2A\u624B\u673A\u53F7\u7801",
      "That table number": "\u8FD9\u4E2A\u684C\u53F7",
      "That email address": "\u8FD9\u4E2A\u90AE\u7BB1\u5730\u5740",
      "That name": "\u8FD9\u4E2A\u540D\u79F0",
      "That web address": "\u8FD9\u4E2A\u7F51\u5740",
      "That SKU": "\u8FD9\u4E2A SKU",
      "That code": "\u8FD9\u4E2A\u4EE3\u7801",
      "That number": "\u8FD9\u4E2A\u53F7\u7801",
      "Something with the same details": "\u8D44\u6599\u76F8\u540C\u7684\u9879\u76EE",
      "{thing} is already in use. Change it, then try again.": "{thing}\u5DF2\u88AB\u4F7F\u7528\u3002\u8BF7\u66F4\u6539\u540E\u91CD\u8BD5\u3002",
      "That didn\u2019t work": "\u64CD\u4F5C\u6CA1\u6709\u6210\u529F",
      "You\u2019re offline. {needs} Connect to the internet, then try again.": "\u60A8\u76EE\u524D\u79BB\u7EBF\u3002{needs}\u8BF7\u8FDE\u63A5\u7F51\u7EDC\u540E\u91CD\u8BD5\u3002",
      "F&B / Cafe / Restaurant": "\u9910\u996E/\u5496\u5561\u9986/\u9910\u5385",
