      "Staff logins and roles": "\u5458\u5DE5\u8D26\u53F7\u548C\u89D2\u8272",
      "The Sellio AI assistant": "Sellio AI \u52A9\u624B",
      "Store design": "\u5E97\u94FA\u8BBE\u8BA1",
      Printing: "\u6253\u5370",
      Listing: "\u5546\u54C1",
      listing: "\u5546\u54C1",
      listings: "\u5546\u54C1",
