      "Start preparing": "\u5F00\u59CB\u51C6\u5907",
      "Mark collected": "\u6807\u8BB0\u4E3A\u5DF2\u81EA\u53D6",
      "Mark delivered": "\u6807\u8BB0\u4E3A\u5DF2\u9001\u8FBE",
      "Plans are managed on the Sellio website": "\u65B9\u6848\u5728 Sellio \u7F51\u7AD9\u4E0A\u7BA1\u7406",
      "This store has reached its monthly order limit. Ask the owner to upgrade the plan.": "\u8FD9\u95F4\u5E97\u94FA\u5DF2\u8FBE\u5230\u6BCF\u6708\u8BA2\u5355\u4E0A\u9650\u3002\u8BF7\u8BA9\u5E97\u4E3B\u5347\u7EA7\u65B9\u6848\u3002",
      "A different ticket for this table may already be in Orders. Check Orders first. If it isn\u2019t there, send this ticket anyway.": "\u8FD9\u684C\u7684\u53E6\u4E00\u5F20\u5355\u53EF\u80FD\u5DF2\u7ECF\u5728\u201C\u8BA2\u5355\u201D\u4E2D\u3002\u8BF7\u5148\u68C0\u67E5\u201C\u8BA2\u5355\u201D\uFF1B\u5982\u679C\u4E0D\u5728\uFF0C\u518D\u53D1\u9001\u8FD9\u5F20\u5355\u3002",
      "The last send wasn\u2019t confirmed": "\u4E0A\u4E00\u6B21\u53D1\u9001\u672A\u5F97\u5230\u786E\u8BA4",
      "This browser stopped Sellio from keeping track of the order, so nothing was sent. Reload the page, then try again.": "\u8FD9\u4E2A\u6D4F\u89C8\u5668\u4E0D\u8BA9 Sellio \u8BB0\u5F55\u8FD9\u5F20\u8BA2\u5355\uFF0C\u6240\u4EE5\u6CA1\u6709\u53D1\u9001\u4EFB\u4F55\u5185\u5BB9\u3002\u8BF7\u91CD\u65B0\u52A0\u8F7D\u9875\u9762\u540E\u91CD\u8BD5\u3002",
      "Couldn\u2019t confirm the order": "\u65E0\u6CD5\u786E\u8BA4\u8BA2\u5355",
      "The connection dropped while sending, so it may or may not have reached the kitchen. Tap Send to kitchen again: if it got there, it isn\u2019t sent twice.": "\u53D1\u9001\u65F6\u7F51\u7EDC\u4E2D\u65AD\uFF0C\u8BA2\u5355\u53EF\u80FD\u5DF2\u9001\u5230\u53A8\u623F\uFF0C\u4E5F\u53EF\u80FD\u6CA1\u6709\u3002\u8BF7\u518D\u70B9\u6309\u201C\u53D1\u9001\u5230\u53A8\u623F\u201D\uFF1A\u5982\u679C\u5DF2\u7ECF\u9001\u5230\uFF0C\u4E0D\u4F1A\u91CD\u590D\u53D1\u9001\u3002",
      "Color Theme": "\u989C\u8272\u4E3B\u9898",
      "Saving theme\u2026": "\u6B63\u5728\u4FDD\u5B58\u4E3B\u9898\u2026",
      "Choose Your Brand Colors": "\u9009\u62E9\u54C1\u724C\u989C\u8272",
      "Saving\u2026": "\u6B63\u5728\u4FDD\u5B58\u2026",
      "You have view-only access to the theme.": "\u60A8\u53EA\u80FD\u67E5\u770B\u4E3B\u9898\uFF0C\u65E0\u6CD5\u4FEE\u6539\u3002",
      "Couldn\u2019t load your selling settings": "\u65E0\u6CD5\u52A0\u8F7D\u60A8\u7684\u9500\u552E\u8BBE\u7F6E",
      "Selling settings saved": "\u9500\u552E\u8BBE\u7F6E\u5DF2\u4FDD\u5B58",
      "Couldn\u2019t save your selling settings": "\u65E0\u6CD5\u4FDD\u5B58\u60A8\u7684\u9500\u552E\u8BBE\u7F6E",
      "Self-collection": "\u81EA\u53D6",
