      "Easier to read": "\u66F4\u6613\u9605\u8BFB",
      Large: "\u5927",
      "Tap the Share icon in Safari\u2019s toolbar": "\u70B9\u6309 Safari \u5DE5\u5177\u680F\u4E2D\u7684\u201C\u5206\u4EAB\u201D\u56FE\u6807",
      'Scroll down and tap "Add to Home Screen"': "\u5411\u4E0B\u6EDA\u52A8\u5E76\u70B9\u6309\u201C\u6DFB\u52A0\u5230\u4E3B\u5C4F\u5E55\u201D",
      'Tap "Add" in the top right corner': "\u70B9\u6309\u53F3\u4E0A\u89D2\u7684\u201C\u6DFB\u52A0\u201D",
      "Tap the Share icon in the address bar": "\u70B9\u6309\u5730\u5740\u680F\u4E2D\u7684\u201C\u5206\u4EAB\u201D\u56FE\u6807",
      'Tap "Add"': "\u70B9\u6309\u201C\u6DFB\u52A0\u201D",
      "Tap the \u22EE menu in the top right of your browser": "\u70B9\u6309\u6D4F\u89C8\u5668\u53F3\u4E0A\u89D2\u7684 \u22EE \u83DC\u5355",
      'Tap "Install app" or "Add to Home screen"': "\u70B9\u6309\u201C\u5B89\u88C5\u5E94\u7528\u201D\u6216\u201C\u6DFB\u52A0\u5230\u4E3B\u5C4F\u5E55\u201D",
      'Confirm by tapping "Install"': "\u70B9\u6309\u201C\u5B89\u88C5\u201D\u786E\u8BA4",
      "Look for the install icon in your browser\u2019s address bar": "\u5728\u6D4F\u89C8\u5668\u7684\u5730\u5740\u680F\u4E2D\u627E\u5230\u5B89\u88C5\u56FE\u6807",
      'Or open the browser menu and choose "Install Sellio"': "\u6216\u6253\u5F00\u6D4F\u89C8\u5668\u83DC\u5355\uFF0C\u9009\u62E9\u201C\u5B89\u88C5 Sellio\u201D",
      "Confirm to add it as an app on your device": "\u786E\u8BA4\u540E\u5373\u53EF\u4F5C\u4E3A\u5E94\u7528\u6DFB\u52A0\u5230\u60A8\u7684\u8BBE\u5907",
      "Add Sellio to your Home Screen": "\u5C06 Sellio \u6DFB\u52A0\u5230\u4E3B\u5C4F\u5E55",
      "Install Sellio on this computer": "\u5728\u8FD9\u53F0\u7535\u8111\u4E0A\u5B89\u88C5 Sellio",
      "Get quick access from your home screen \u2014 no app store needed. It opens like a real app.": "\u4ECE\u4E3B\u5C4F\u5E55\u5FEB\u901F\u6253\u5F00\uFF0C\u65E0\u9700\u5E94\u7528\u5546\u5E97\u3002\u6253\u5F00\u540E\u5C31\u50CF\u771F\u6B63\u7684\u5E94\u7528\u4E00\u6837\u3002",
      "Got it": "\u77E5\u9053\u4E86",
      "Could not copy. Press and hold the link to copy it.": "\u65E0\u6CD5\u590D\u5236\u3002\u8BF7\u957F\u6309\u94FE\u63A5\u8FDB\u884C\u590D\u5236\u3002",
      "Order from my shop here {link}": "\u5728\u8FD9\u91CC\u5411\u6211\u7684\u5E97\u94FA\u4E0B\u5355 {link}",
      "{shopName}: order from my shop here {link}": "{shopName}\uFF1A\u5728\u8FD9\u91CC\u5411\u6211\u7684\u5E97\u94FA\u4E0B\u5355 {link}",
      "Your store page": "\u60A8\u7684\u5E97\u94FA\u9875\u9762",
      Copied: "\u5DF2\u590D\u5236",
      "QR code for your store page": "\u60A8\u7684\u5E97\u94FA\u9875\u9762\u4E8C\u7EF4\u7801",
      "Save QR code": "\u4FDD\u5B58\u4E8C\u7EF4\u7801",
      "Couldn\u2019t get the QR code ready to save. Take a screenshot of it instead.": "\u4E8C\u7EF4\u7801\u672A\u80FD\u51C6\u5907\u597D\u4FDD\u5B58\uFF0C\u8BF7\u6539\u4E3A\u622A\u56FE\u3002",
      "Getting your QR code ready\u2026": "\u6B63\u5728\u51C6\u5907\u4E8C\u7EF4\u7801\u2026",
      "Open my store page": "\u6253\u5F00\u6211\u7684\u5E97\u94FA\u9875\u9762",
      "8 digits, starting with 8 or 9": "8 \u4F4D\u6570\u5B57\uFF0C\u4EE5 8 \u6216 9 \u5F00\u5934",
      "9\u201310 digits, starting with 1": "9\u201310 \u4F4D\u6570\u5B57\uFF0C\u4EE5 1 \u5F00\u5934",
      "9\u201312 digits, starting with 8": "9\u201312 \u4F4D\u6570\u5B57\uFF0C\u4EE5 8 \u5F00\u5934",
      "Please sign in again.": "\u8BF7\u91CD\u65B0\u767B\u5F55\u3002",
      "This is a staff login. Staff sign in with their phone number on the login page.": "\u8FD9\u662F\u5458\u5DE5\u8D26\u53F7\u3002\u5458\u5DE5\u8BF7\u5728\u767B\u5F55\u9875\u9762\u7528\u624B\u673A\u53F7\u7801\u767B\u5F55\u3002",
      "Please open the verification link we emailed you, then try again.": "\u8BF7\u6253\u5F00\u6211\u4EEC\u53D1\u5230\u60A8\u90AE\u7BB1\u7684\u9A8C\u8BC1\u94FE\u63A5\uFF0C\u7136\u540E\u91CD\u8BD5\u3002",
      "Please enter your name.": "\u8BF7\u8F93\u5165\u60A8\u7684\u59D3\u540D\u3002",
      "Please enter a valid mobile number.": "\u8BF7\u8F93\u5165\u6709\u6548\u7684\u624B\u673A\u53F7\u7801\u3002",
      "This phone number is already used by another Sellio account (it may be a staff login). Use a different number, or contact sellio@apptelier.sg.": "\u8FD9\u4E2A\u624B\u673A\u53F7\u7801\u5DF2\u88AB\u53E6\u4E00\u4E2A Sellio \u8D26\u53F7\u4F7F\u7528\uFF08\u53EF\u80FD\u662F\u5458\u5DE5\u8D26\u53F7\uFF09\u3002\u8BF7\u4F7F\u7528\u5176\u4ED6\u53F7\u7801\uFF0C\u6216\u8054\u7CFB sellio@apptelier.sg\u3002",
      "Please finish setting up your account first.": "\u8BF7\u5148\u5B8C\u6210\u8D26\u53F7\u8BBE\u7F6E\u3002",
      "This account already has a store. Sign in to manage it, or contact sellio@apptelier.sg to open another one.": "\u8FD9\u4E2A\u8D26\u53F7\u5DF2\u7ECF\u6709\u5E97\u94FA\u4E86\u3002\u8BF7\u767B\u5F55\u7BA1\u7406\uFF0C\u6216\u8054\u7CFB sellio@apptelier.sg \u5F00\u8BBE\u53E6\u4E00\u95F4\u5E97\u94FA\u3002",
      "We couldn\u2019t create a web address for this name. Please try a different shop name.": "\u65E0\u6CD5\u7528\u8FD9\u4E2A\u540D\u79F0\u521B\u5EFA\u7F51\u5740\uFF0C\u8BF7\u6362\u4E00\u4E2A\u5E97\u94FA\u540D\u79F0\u3002",
      "We\u2019re sending a lot of emails right now. Please try again in a few minutes.": "\u6211\u4EEC\u73B0\u5728\u53D1\u9001\u7684\u90AE\u4EF6\u5F88\u591A\uFF0C\u8BF7\u51E0\u5206\u949F\u540E\u518D\u8BD5\u3002",
      "Please wait {seconds} seconds before asking for another link.": "\u8BF7\u7B49 {seconds} \u79D2\u540E\u518D\u7533\u8BF7\u65B0\u94FE\u63A5\u3002",
      "Please choose a longer password (at least 6 characters).": "\u8BF7\u8BBE\u7F6E\u66F4\u957F\u7684\u5BC6\u7801\uFF08\u81F3\u5C11 6 \u4E2A\u5B57\u7B26\uFF09\u3002",
