      "(optional)": "\uFF08\u9009\u586B\uFF09",
      "Your comment": "\u60A8\u7684\u8BC4\u8BBA",
      "e.g. Lovely cake, easy collection": "\u4F8B\u5982\uFF1A\u86CB\u7CD5\u5F88\u597D\u5403\uFF0C\u81EA\u53D6\u5F88\u65B9\u4FBF",
      "Show my comment on {shop}\u2019s page as {name}": "\u5728{shop}\u7684\u9875\u9762\u4E0A\u663E\u793A\u6211\u7684\u8BC4\u8BBA\uFF0C\u7F72\u540D\u4E3A{name}",
      "your first name and initial": "\u60A8\u7684\u540D\u5B57\u548C\u59D3\u6C0F\u9996\u5B57\u6BCD",
