      "We couldn't load your ratings just now.": "\u6682\u65F6\u65E0\u6CD5\u52A0\u8F7D\u60A8\u7684\u8BC4\u5206\u3002",
      "No ratings yet. Buyers can rate an order once you mark it {doneWords}.": "\u8FD8\u6CA1\u6709\u8BC4\u5206\u3002\u60A8\u5C06\u8BA2\u5355\u6807\u8BB0\u4E3A{doneWords}\u540E\uFF0C\u4E70\u5BB6\u5C31\u53EF\u4EE5\u8BC4\u5206\u3002",
      "1 buyer has rated you ({week} this week).": "\u5DF2\u6709 1 \u4F4D\u4E70\u5BB6\u4E3A\u60A8\u8BC4\u5206\uFF08\u672C\u5468 {week} \u4F4D\uFF09\u3002",
      "1 buyer has rated you.": "\u5DF2\u6709 1 \u4F4D\u4E70\u5BB6\u4E3A\u60A8\u8BC4\u5206\u3002",
