      "{count} buyers have rated you.": "\u5DF2\u6709 {count} \u4F4D\u4E70\u5BB6\u4E3A\u60A8\u8BC4\u5206\u3002",
      "Shown on Explore and your listings. Hidden on your ordering page.": "\u663E\u793A\u5728\u201C\u53D1\u73B0\u201D\u548C\u60A8\u7684\u5546\u54C1\u4E0A\uFF0C\u4E0D\u663E\u793A\u5728\u60A8\u7684\u70B9\u5355\u9875\u9762\u3002",
      "Shown on Explore, your listings and your shop page.": "\u663E\u793A\u5728\u201C\u53D1\u73B0\u201D\u3001\u60A8\u7684\u5546\u54C1\u548C\u5E97\u94FA\u9875\u9762\u4E0A\u3002",
      "Buyers see your average once 3 buyers have rated you ({count} so far).": "\u6709 3 \u4F4D\u4E70\u5BB6\u8BC4\u5206\u540E\uFF0C\u4E70\u5BB6\u5C31\u80FD\u770B\u5230\u60A8\u7684\u5E73\u5747\u5206\uFF08\u76EE\u524D {count} \u4F4D\uFF09\u3002",
      "Hide it on your ordering page": "\u5728\u70B9\u5355\u9875\u9762\u9690\u85CF",
      "Show it on your ordering page": "\u5728\u70B9\u5355\u9875\u9762\u663E\u793A",
