      Latest: "\u6700\u65B0",
      "A buyer": "\u4E00\u4F4D\u4E70\u5BB6",
      "(only you see this)": "\uFF08\u53EA\u6709\u60A8\u770B\u5F97\u5230\uFF09",
      "Shown on your shop page": "\u663E\u793A\u5728\u60A8\u7684\u5E97\u94FA\u9875\u9762\u4E0A",
      "Hidden from your shop page while Sellio looks at a report": "Sellio \u5BA1\u6838\u4E3E\u62A5\u671F\u95F4\uFF0C\u4E0D\u5728\u60A8\u7684\u5E97\u94FA\u9875\u9762\u663E\u793A",
      "Comment removed by Sellio": "\u8BC4\u8BBA\u5DF2\u88AB Sellio \u79FB\u9664",
      Loading: "\u52A0\u8F7D\u4E2D",
      "This is taking longer than usual.": "\u8FD9\u6BD4\u5E73\u65F6\u82B1\u4E86\u66F4\u957F\u65F6\u95F4\u3002",
      Reload: "\u91CD\u65B0\u52A0\u8F7D",
      "Did you mean {suggestion}?": "\u60A8\u662F\u4E0D\u662F\u8981\u627E{suggestion}\uFF1F",
      "This listing isn't available.": "\u8FD9\u4EF6\u5546\u54C1\u5DF2\u65E0\u6CD5\u67E5\u770B\u3002",
      "You can't like your own listing.": "\u60A8\u4E0D\u80FD\u559C\u6B22\u81EA\u5DF1\u7684\u5546\u54C1\u3002",
      "You've liked a lot today. Try again tomorrow.": "\u60A8\u4ECA\u5929\u5DF2\u7ECF\u559C\u6B22\u592A\u591A\u5546\u54C1\u4E86\uFF0C\u8BF7\u660E\u5929\u518D\u8BD5\u3002",
      "Couldn\u2019t update your like. Check your connection and try again.": "\u65E0\u6CD5\u66F4\u65B0\u559C\u6B22\u72B6\u6001\u3002\u8BF7\u68C0\u67E5\u7F51\u7EDC\u540E\u91CD\u8BD5\u3002",
      "1 like": "1 \u4EBA\u559C\u6B22",
      "{count} likes": "{count} \u4EBA\u559C\u6B22",
      Good: "\u597D",
      Great: "\u5F88\u597D",
      "Not good": "\u8F83\u5DEE",
      Okay: "\u4E00\u822C",
      Terrible: "\u5F88\u5DEE",
      "Log in to rate your order.": "\u767B\u5F55\u540E\u5373\u53EF\u4E3A\u8BA2\u5355\u8BC4\u5206\u3002",
      "Your rating couldn't be saved. Please try again.": "\u65E0\u6CD5\u4FDD\u5B58\u60A8\u7684\u8BC4\u5206\uFF0C\u8BF7\u91CD\u8BD5\u3002",
      "Couldn\u2019t remove it. Please try again.": "\u65E0\u6CD5\u79FB\u9664\uFF0C\u8BF7\u91CD\u8BD5\u3002",
      "Rude, hateful or harassing": "\u7C97\u9C81\u3001\u4EC7\u6068\u6216\u9A9A\u6270",
      "Shares someone\u2019s personal details": "\u6CC4\u9732\u4ED6\u4EBA\u7684\u4E2A\u4EBA\u8D44\u6599",
      "Spam or advertising": "\u5783\u573E\u4FE1\u606F\u6216\u5E7F\u544A",
