      "Something else": "\u5176\u4ED6\u539F\u56E0",
      "Couldn\u2019t send the report. Please try again.": "\u65E0\u6CD5\u63D0\u4EA4\u4E3E\u62A5\uFF0C\u8BF7\u91CD\u8BD5\u3002",
      "Log in to report a comment.": "\u767B\u5F55\u540E\u5373\u53EF\u4E3E\u62A5\u8BC4\u8BBA\u3002",
      "Please keep it respectful: rude or hateful words can't be posted publicly.": "\u8BF7\u4FDD\u6301\u793C\u8C8C\uFF1A\u7C97\u9C81\u6216\u4EC7\u6068\u7684\u8A00\u8BBA\u4E0D\u80FD\u516C\u5F00\u53D1\u5E03\u3002",
      "Public comments can't include addresses, postal codes, block or unit numbers. Take them out, or keep your comment private.": "\u516C\u5F00\u8BC4\u8BBA\u4E0D\u80FD\u5305\u542B\u5730\u5740\u3001\u90AE\u7F16\u3001\u5EA7\u53F7\u6216\u5355\u4F4D\u53F7\u7801\u3002\u8BF7\u5220\u9664\u8FD9\u4E9B\u5185\u5BB9\uFF0C\u6216\u5C06\u8BC4\u8BBA\u8BBE\u4E3A\u4E0D\u516C\u5F00\u3002",
      "Public comments can't include phone numbers, emails, links or social media handles. Take them out, or keep your comment private.": "\u516C\u5F00\u8BC4\u8BBA\u4E0D\u80FD\u5305\u542B\u7535\u8BDD\u53F7\u7801\u3001\u90AE\u7BB1\u3001\u94FE\u63A5\u6216\u793E\u4EA4\u5A92\u4F53\u8D26\u53F7\u3002\u8BF7\u5220\u9664\u8FD9\u4E9B\u5185\u5BB9\uFF0C\u6216\u5C06\u8BC4\u8BBA\u8BBE\u4E3A\u4E0D\u516C\u5F00\u3002",
      "Public comments can't include NRIC or FIN numbers. Please take it out.": "\u516C\u5F00\u8BC4\u8BBA\u4E0D\u80FD\u5305\u542B NRIC \u6216 FIN \u53F7\u7801\uFF0C\u8BF7\u5220\u9664\u3002",
      "You can rate this order once it's done.": "\u8BA2\u5355\u5B8C\u6210\u540E\u5373\u53EF\u8BC4\u5206\u3002",
      "This order can't be rated.": "\u8FD9\u5F20\u8BA2\u5355\u65E0\u6CD5\u8BC4\u5206\u3002",
      "Your note can be up to 300 characters.": "\u5907\u6CE8\u6700\u591A 300 \u4E2A\u5B57\u7B26\u3002",
      "This order was placed with another account.": "\u8FD9\u5F20\u8BA2\u5355\u662F\u7528\u53E6\u4E00\u4E2A\u8D26\u53F7\u4E0B\u7684\u3002",
      "This order was rated from another account.": "\u8FD9\u5F20\u8BA2\u5355\u5DF2\u7531\u53E6\u4E00\u4E2A\u8D26\u53F7\u8BC4\u5206\u3002",
      "You can't rate your own shop.": "\u60A8\u4E0D\u80FD\u4E3A\u81EA\u5DF1\u7684\u5E97\u94FA\u8BC4\u5206\u3002",
      "You've rated a lot today. Try again tomorrow.": "\u60A8\u4ECA\u5929\u5DF2\u7ECF\u8BC4\u5206\u592A\u591A\u6B21\u4E86\uFF0C\u8BF7\u660E\u5929\u518D\u8BD5\u3002",
      "You can't rate this shop from a phone that's used to run it.": "\u4E0D\u80FD\u7528\u7ECF\u8425\u8FD9\u95F4\u5E97\u94FA\u7684\u624B\u673A\u4E3A\u5B83\u8BC4\u5206\u3002",
      "Choose from 1 to 5 stars.": "\u8BF7\u9009\u62E9 1 \u5230 5 \u661F\u3002",
      "This order is too old to rate.": "\u8FD9\u5F20\u8BA2\u5355\u592A\u4E45\u4E86\uFF0C\u65E0\u6CD5\u8BC4\u5206\u3002",
      "Ratings can be changed for 30 days.": "\u8BC4\u5206\u5728 30 \u5929\u5185\u53EF\u4EE5\u4FEE\u6539\u3002",
      "This rating isn't yours.": "\u8FD9\u4E0D\u662F\u60A8\u7684\u8BC4\u5206\u3002",
      "Log in first.": "\u8BF7\u5148\u767B\u5F55\u3002",
