      "What happens when you ask:": "Apa yang berlaku apabila anda meminta:",
      "Your request is in.": "Permintaan anda telah diterima.",
      "Turn off email notifications?": "Matikan pemberitahuan e-mel?",
      "Turn off order alerts?": "Matikan amaran pesanan?",
      "If turned off, you won't be able to receive password reset links or other account and marketing emails in future.": "Jika dimatikan, anda tidak akan dapat menerima pautan tetapan semula kata laluan atau e-mel akaun dan pemasaran lain pada masa hadapan.",
      "If turned off, you won't be notified when new orders come in \u2014 on this page, in Orders, or on the Kitchen Display.": "Jika dimatikan, anda tidak akan dimaklumkan apabila pesanan baharu masuk \u2014 di halaman ini, di Pesanan atau di Paparan Dapur.",
