      "Turn off order alerts?": "Matikan notifikasi pesanan?",
      "If turned off, you won't be able to receive password reset links or other account and marketing emails in future.": "Jika dimatikan, Anda tidak akan menerima tautan reset kata sandi atau email akun dan pemasaran lainnya ke depannya.",
      "If turned off, you won't be notified when new orders come in \u2014 on this page, in Orders, or on the Kitchen Display.": "Jika dimatikan, Anda tidak akan diberi tahu saat ada pesanan baru \u2014 di halaman ini, di Pesanan, atau di Layar Dapur.",
